  /** Shop where the purchase took place. */
  shop: Shop;

  /**
   * The renderer version being used for the extension.
   *
   * @example 'unstable'
   */
  version: Version;

  /**
   * The requireLogin() method triggers login if the customer is viewing pre-authenticated Order status page.
   */
